    CHECK (block_offset IN ('exact', 'start', 'middle', 'end', 'NONE')),
    CHECK (block_offset IS NULL OR block_offset NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (universe_basis IN ('LONGEST_FINITE_RUN', 'PARTITION_UPPER_BOUND', 'NONE')),
    CHECK (universe_basis IS NULL OR universe_basis NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
