    code_sha256 TEXT NOT NULL,
    CHECK (run_id IS NULL OR run_id NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (dataset_id IS NULL OR dataset_id NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (variable_id IS NULL OR variable_id NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (variable_type IN ('NUMERIC', 'TEXT', 'TIMESTAMP', 'UNKNOWN')),
    CHECK (variable_type IS NULL OR variable_type NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (partition IS NULL OR partition NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (metric IS NULL OR metric NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (operator IS NULL OR operator NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (policy IS NULL OR policy NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (applicability IN ('APPLICABLE', 'NOT_APPLICABLE', 'UNDETERMINED')),
    CHECK (applicability IS NULL OR applicability NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (applicability_rule IS NULL OR applicability_rule NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (state IN ('RESULT', 'INCONCLUSIVE', 'UNAVAILABLE', 'NOT_APPLICABLE', 'NOT_RUN', 'REFUSED', 'FAILED', 'RESOURCE_EXCEEDED', 'UNCERTAIN')),
    CHECK (state IS NULL OR state NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (state_source IN ('ROWS', 'DATASET_TERMINAL', 'DECLARATION', 'NO_EVIDENCE')),
    CHECK (state_source IS NULL OR state_source NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (code_sha256 IS NULL OR code_sha256 NOT IN ('PUBLICLY_ELIGIBLE', 'LIVE_ELIGIBLE')),
    CHECK (state <> 'NOT_APPLICABLE' OR (applicability = 'NOT_APPLICABLE' AND state_source = 'DECLARATION')),
    CHECK (applicability <> 'NOT_APPLICABLE' OR state IN ('NOT_APPLICABLE', 'UNCERTAIN')),
    CHECK (state_source <> 'ROWS' OR rows > 0),
    CHECK (state_source <> 'NO_EVIDENCE' OR (rows = 0 AND state = 'NOT_RUN')),
    CHECK (state_source <> 'DATASET_TERMINAL' OR (rows = 0 AND state IN ('INCONCLUSIVE', 'REFUSED', 'FAILED', 'RESOURCE_EXCEEDED', 'UNCERTAIN'))),
    CHECK (state_source <> 'DECLARATION' OR state = 'NOT_APPLICABLE'),
    loaded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

